self.KB_CONTENT["card:780475"]={"id":"card:780475","ty":"card","sourceId":"780475","title":"『IPSR18 SHIPPING INSTRUCTION(文字報表)』中的『列印單價金額』為何？","ver":"GP4以上","topic":"權限","keywords":["權限","單價"],"y":"other","answer":"* 使用者需有售價權限才勾選是否列印單價金額。* 若列印單價金額為「N」時，則單價，金額皆不印。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
