self.KB_CONTENT["card:779484"]={"id":"card:779484","ty":"card","sourceId":"779484","title":"『委工單單據性質設定作業(IDLI07)』中的『編碼方式 (MQ004)』為何？","ver":"GP4以上","topic":"編號","keywords":["編號","工單","手動","編碼"],"y":"other","answer":"* 分為1.日編、2.月編、3.流水號及4.手動編號四種編碼方式。* 不可空白。* 當編碼方式為「日編」或「月編」時才可輸入 [年碼數] 欄位資料。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
