self.KB_CONTENT["card:792106"]={"id":"card:792106","ty":"card","sourceId":"792106","title":"『保修記錄表』中的『選擇保修單單號 (TG001+TG002)』為何？","ver":"GP4以上","topic":"單號","keywords":["單號","工單","單頭","保修"],"y":"other","answer":"* 可按(icon)或[F2]保修工單單頭檔，以輸入要列印哪些保修工單的保修記錄資料。* 空白表示全部。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
