self.KB_CONTENT["card:750801"]={"id":"card:750801","ty":"card","sourceId":"750801","title":"『會計科目設定作業』中的『專用發票限定金額 (MA021)』為何？","ver":"iGP","topic":"發票","keywords":["發票","科目","幣別","大於"],"y":"other","answer":"* 共用參數設定作業之「功能別」為2.中國大陸版時，此欄位才顯示。* 此欄位必須大於等於零。* 依本國幣別做金額取位。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
