self.KB_CONTENT["card:776984"]={"id":"card:776984","ty":"card","sourceId":"776984","title":"『多角貿易銷退單拋轉作業』的作業目的為何？","ver":"GP4以上","topic":"多角貿易","keywords":["多角貿易","銷退單","貨單","廠商"],"y":"explain","answer":"『多角貿易銷退單』確認後，可利用此作業來進行後續單據的拋轉作業，將依流程設定順序來產生「來源公司」的『退貨單』，各「下游廠商」的『銷退單』、『退貨單』及「最終廠商」的『銷退單』等單據。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
