self.KB_CONTENT["field:847743"]={"id":"field:847743","ty":"field","sourceId":"847743","title":"總提效率","ver":"GP40.iGP 以上","topic":"","keywords":[],"job":"專案預算彙總表列印作業","code":"","answer":"總提效率(目標) = (目標執行預算總額(未稅)(TA110)-未稅實際總額(TA017)) / 目標執行預算總額(未稅)(TA110)","file":"fields.jsonl"};
