self.KB_CONTENT["field:753088"]={"id":"field:753088","ty":"field","sourceId":"753088","title":"期別","ver":"iGP","topic":"","keywords":[],"job":"餘額自動分攤作業","code":"ACT.NV010","answer":"* 僅顯示。* 預設來源科目之期別為會計現行期別（依據總帳帳別資料建立作業(ACTI31)中相同總帳帳別的設定）。","file":"fields.jsonl"};
